-- Full Spectrum grants: batch 3 (verified against funder pages on 2026-10-31).
-- 11 new funders + corrections to LPMC and Polk Bros. Idempotent; safe to re-run.
-- Apply: supabase db query --linked -f supabase/fs-grants-batch3.sql
begin;
select count(*) as before_total from fs_grant_deadlines;

insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates)
select * from (values
('Peoples Gas (WEC Energy Group)','Community Fund: program/project grant','dated','2027-01-31'::date,null::date,'not published',true,'https://www.wecenergygroup.com/community/peoples-gas-charitable-giving.htm','Quarterly deadlines Jan 31, Apr 30, Jul 31, Oct 31 (Oct 31 2026 is today: aim for Jan 31). Jan 31 2027 is a Sunday; submit by Fri Jan 29. Focus areas include arts and culture, education, community and neighborhood development. One award per org per calendar year. New Blackbaud account required (since Jul 1 2026). Separate sponsorship application exists. Contact 312-240-7516, PGL-NSGCharitablegiving@wecenergygroup.com. Confirm service area covers Rainbow Beach / South Shore (Chicago).','2026-10-31'::date,'corporate','djclass',1,'Eligible 501(c)(3) in the Peoples Gas service area; not individuals, religious, athletics, trips',null,'to_research','{g0}'::text[]),
('Cliff Dwellers Arts Foundation','Arts Foundation grant','expected','2027-03-26'::date,null::date,'unconfirmed (reported under $2,000)',false,'https://cliff-chicago.org/foundation/','Deadlines are the last Friday in March and September (Mar 27 2026, Sep 25 2026), so Mar 26 2027 by that rule. The $2,000 cap and capital-expense exclusion were NOT on the page text we read: check the guidelines PDF. Online application. Contact artsfoundation@cliff-chicago.org. Frame as a contained project (guest-artist series or showcase), not controllers.','2026-10-31'::date,'foundation','djclass',2,'Arts organizations and individuals (per site)',null,'to_research','{g0}'::text[]),
('Levitate Foundation','Community Grants (Passion Projects)','expected','2027-01-01'::date,null::date,'up to $10,000',false,'https://levitatefoundation.org/passion-projects/','Page says applications are open for 2026; the Jan 1 2027 deadline in the research is UNVERIFIED (check the application form https://form.jotform.com/262735554942162). No geographic limit stated for Community Grants (other Levitate programs are Massachusetts). Ask whether Chicago is eligible before drafting. Fits free arts workshops, youth mentorship, community stage.','2026-10-31'::date,'foundation','wednesdays',2,'Artists, educators, community leaders; individuals and nonprofits. Confirm Chicago eligibility.',null,'to_research','{g0}'::text[]),
('Kars4Kids','Small Grant Program','rolling',null,null,'typically $5,000',true,'https://www.kars4kidsgrants.org/','Short online application: mission/program summary, Tax ID, IRS letter. No deadline; decision in 4-6 months, up to a year; no phone consultations. ELIGIBILITY RISK: applicant primary mission must be serving children and secular; Ras Tafari Inc. is a cultural festival org, so frame the application around the DJ Lab and confirm fit. Use for future money, not urgent bills.','2026-10-31'::date,'foundation','djclass',3,'US 501(c)(3), primary mission serving children, secular',null,'to_research','{g0}'::text[]),
('Aitel Foundation','Small youth-engagement grants','rolling',null,null,'not published',true,'https://www.aitelfoundation.org/funding','Email funding@aitelfoundation.org to request funding (general: info@aitelfoundation.org). Applicant must be affiliated with a nonprofit. Amounts, deadlines and geography are not published: ask about Chicago eligibility, availability and typical size.','2026-10-31'::date,'foundation','djclass',3,'Affiliated with a nonprofit; high-impact youth engagement',null,'to_research','{g0}'::text[]),
('Strong Mind Strong Body Foundation','Community Grants Program','rolling',null,null,'$150-$1,500',true,'https://strongmindstrongbody.org/community/','Eligibility inquiry first (purpose statement 50 words or less), then a one-page application. Project must serve a single neighborhood. GEOGRAPHY RISK: focuses mostly on Upper Midwest, Great Plains, Southern California, Hawaii and Oregon (not stated as exclusive). Education and youth services qualify. No deadlines listed.','2026-10-31'::date,'foundation','wednesdays',3,'Nonprofits only; single neighborhood; education, youth services, health',null,'to_research','{g0}'::text[]),
('Karma for Cara Foundation','Youth Service Microgrants','dated','2027-01-01'::date,null::date,'$250-$1,000',true,'https://karmaforcara.org/microgrant-application','Reviewed quarterly: Jan 1, Apr 1, Jul 1, Oct 1 (11:59 EST); late applications roll to the next deadline. Applicant must be a student 18 or younger; project must include other youth. Excluded: stipends, facility rentals, transportation, gift cards, prizes. Discourages buy-and-donate projects. Materials only, never artist pay. A student leader has to apply, not the organization.','2026-10-31'::date,'foundation','wednesdays',3,'Students 18 or younger lead the application; US projects',null,'to_research','{}'::text[]),
('New York Life Foundation','Community Impact Grants (workplace grants)','relationship',null,null,'$5,000-$25,000',true,'https://www.newyorklife.com/foundation/grant-opportunities/workplace-grants','A New York Life field employee or agent must champion the nonprofit and apply for it. No deadlines or cycle on the page: get them from the champion. First step is finding a local agent who would volunteer with Full Spectrum (for example youth budgeting and the business of DJing).','2026-10-31'::date,'corporate','djclass',3,'Needs an employee or agent champion',null,'to_research','{g4}'::text[]),
('Ignite Fund','Artist project grants (Round 6)','paused',null,null,'$10,000 x 6 grants',true,'https://ignitefund.org/en/apply','Round 5 closed Apr 13 2026; next opening not announced (newsletter). Applicant must be an individual 18+ in Cook, DuPage, Kane, McHenry, Lake or Will county and cannot be led by an incorporated entity, school or religious entity, so Ras Tafari Inc. cannot apply. Only the independent visual artists on the neighborhood-pride installations could, leading the work themselves. Not a Full Spectrum application.','2026-10-31'::date,'foundation','wednesdays',3,'Individual artists or collectives; not incorporated entities',null,'not_eligible','{}'::text[]),
('Service Club of Chicago','Equipment grants','dated','2027-01-15'::date,'2026-12-01'::date,'not published',true,'https://theserviceclubofchicago.org/grants/application-guidelines/','Window Dec 1 to Jan 15, online, plus ONE PAPER COPY with all supporting documents dropped at 233 East Erie, Suite 405. Pays vendors directly for non-recurring purchases (no salaries or rent); two bids per item. NOT ELIGIBLE NOW: needs 3 years of operation, latest Form 990, audited or CPA-reviewed full-year financials. Office must be within 25 miles of 233 E Erie. Revisit once the org has history.','2026-10-31'::date,'foundation','djclass',3,'501(c)(3) in operation 3+ years; audited or reviewed financials',null,'not_eligible','{g2,g3}'::text[]),
('Driehaus Foundation','Arts and Culture: Chicago-rooted festival / shared platform (Category C)','relationship',null,null,'$30,000-$1,000,000 project budgets',true,'https://driehausfoundation.org/funding/arts-and-culture','Does NOT fund arts education or arts learning, so not the DJ Lab. Category C budgets $30,000 to $1 million for Chicago-rooted art forms: only a house-music or Chicago-roots presentation platform could fit. Whether it is invitation-only was not on the page we read: confirm via the Inquiry and Application Process section. Contact Lori Dimun, loridimun@driehausfoundation.org, 312-641-5772 x113. Also on the BBPAC tracker.','2026-10-31'::date,'foundation','selassiefest',3,'Chicago programming; no arts learning',null,'to_research','{g1,g2,g4}'::text[])
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);

-- LPMC: page confirms 2027 applications are open (the old "listing seemed stale" note is superseded)
update fs_grant_deadlines set
  verified = true, verified_on = '2026-10-31',
  notes = 'CONFIRMED 2026-10-31: lpmcfoundation.org/now-accepting-applications says 2027 applications are open, rolling until the annual limit is reached. Up to $30,000 a year shared among one or more tax-exempt orgs. Programs connecting Chicago students to music. Email LPMCGrants@LPMCFoundation.org and download the requirements document first (detailed criteria were not on the page; the PDF would not load). Lead with free, sustained DJ instruction and measurable learning.'
where funder = 'LPMC Foundation' and program = 'General Grants Program';

-- Polk Bros.: open-application introductions now exist (replaces "paused / not accepting")
update fs_grant_deadlines set
  kind = 'dated', deadline_date = '2026-12-04', verified = true, verified_on = '2026-10-31',
  url = 'https://www.polkbrosfdn.org/our-grantmaking/open-application',
  program = 'Open Application (introduction)',
  notes = 'CONFIRMED 2026-10-31: introductions accepted year-round; deadlines (5pm CT) Dec 4 2026 (May 2027 board), Mar 5 2027 (Aug 2027), Jun 4 2027 (Nov 2027), Aug 20 2027. An introduction does not guarantee an invitation to submit a full proposal. Requires 501(c)(3) or fiscal sponsor, operates in or serves Chicago, in operation at least ONE YEAR, and a Form 990 filed for one of the two most recent fiscal years. Ras Tafari Inc. likely does not meet the 990 / one-year test yet (first 990 mid-May 2027), so treat Mar 5 or Jun 4 2027 as the realistic target. Grant sizes not published: call 312-527-4684.',
  eligibility = '501(c)(3), 1+ year in operation, recent Form 990, serves Chicago'
where funder = 'Polk Bros. Foundation' and program = 'Small grants (up to $25,000)';

select count(*) as after_total from fs_grant_deadlines;
select funder, program, kind, deadline_date, verified, status from fs_grant_deadlines
where verified_on = '2026-10-31' order by funder;
commit;
